import { LinkGroupComponent } from './link-group.component';
import { LinkComponent } from '../link';

@Component({
  selector: 'app-demo',
  imports: [LinkGroupComponent, LinkComponent],
  template: `
    <dma-link-group>
        <h2>{{ heading }}</h2>
        @for (link of links; track $index) {
        <li>
            <a dma-link kind="quiet" href="#">{{ link }}</a>
        </li>
        }
    </dma-link-group>`,
})
